package top.pxczxn.community.web.performance;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.core.annotation.Order; import org.springframework.stereotype.Component; import java.io.IOException;
@Component @Order(20) public class PublicPerformanceFilter implements Filter { public void doFilter(ServletRequest request,ServletResponse response,FilterChain chain)throws IOException,ServletException {long start=System.nanoTime();try{chain.doFilter(request,response);}finally{if(request instanceof HttpServletRequest r&&response instanceof HttpServletResponse h&&"GET".equals(r.getMethod())&&r.getRequestURI().startsWith("/api/v1/public/")){if(h.getHeader("Cache-Control")==null)h.setHeader("Cache-Control","public, max-age=60, stale-while-revalidate=120");h.setHeader("Server-Timing","app;dur="+String.format(java.util.Locale.ROOT,"%.2f",(System.nanoTime()-start)/1_000_000d));}}} }
